"""Reproducible LOCAL DEMO fixtures; generated bytes are never committed."""
import json
from pathlib import Path


def fixtures(*, extended=False):
    import pymupdf
    root = Path(__file__).resolve().parents[2] / 'backend/tests/documents/fixtures'
    cases = []
    for name, kind in [('payslip', 'liquidacion_sueldo'), ('savings', 'certificado_ahorro'),
                       ('employment', 'documento_laboral')]:
        cases.append((name, kind, json.loads((root / (name + '.json')).read_text(encoding='utf-8'))['content']))
    cases.extend([
        ('missing', 'liquidacion_sueldo', 'LOCAL DEMO - LIQUIDACION SINTETICA\nTotal haberes: $1.500.000\nNo contiene liquido ni datos personales reales.'),
        ('ambiguous', 'liquidacion_sueldo', 'LOCAL DEMO - LIQUIDACION SINTETICA\nLiquido a pagar: $1.200.000\nLiquido a pagar: $1.100.000'),
    ])
    for name, kind, content in cases:
        with pymupdf.open() as doc:
            page = doc.new_page(width=595, height=842)
            page.insert_text((40, 45), 'LOCAL DEMO - SIN VALIDEZ', fontsize=13)
            page.insert_textbox(pymupdf.Rect(40, 80, 555, 700), content, fontsize=14)
            embedded = doc.tobytes()
            pixmap = page.get_pixmap(dpi=200, colorspace=pymupdf.csGRAY)
            png = pixmap.tobytes('png')
            jpeg = pixmap.tobytes('jpeg')
        yield name + '_embedded', kind, 'pdf', embedded
        with pymupdf.open() as scan:
            page = scan.new_page(width=595, height=842)
            page.insert_image(page.rect, stream=png)
            yield name + '_scan', kind, 'pdf', scan.tobytes()
            if name == 'payslip':
                page.set_rotation(90)
                yield name + '_rotated_scan', kind, 'pdf', scan.tobytes()
                if extended:
                    for angle in (180, 270):
                        page.set_rotation(angle)
                        yield name + f'_rotated_{angle}', kind, 'pdf', scan.tobytes()
        if name == 'payslip':
            yield name + '_png', kind, 'png', png
            yield name + '_jpeg', kind, 'jpeg', jpeg
            if extended:
                yield from stress_fixtures(kind, content)
        if name == 'employment' and extended:
            yield from mixed_orientation_fixture(kind)


def stress_fixtures(kind, content):
    """Deterministic synthetic degradation; only standard library and PyMuPDF."""
    import pymupdf
    import random

    with pymupdf.open() as source:
        page = source.new_page(width=595, height=842)
        page.insert_text((40, 45), 'LOCAL DEMO - SIN VALIDEZ', fontsize=13)
        page.insert_textbox(pymupdf.Rect(40, 80, 555, 700), content, fontsize=14)
        low = page.get_pixmap(dpi=75, colorspace=pymupdf.csGRAY).tobytes('png')
        pix = page.get_pixmap(dpi=160, colorspace=pymupdf.csGRAY)
        pixels = pix.samples
        contrast = bytes(130 + value * 65 // 255 for value in pixels)
        rng = random.Random(2301)
        noise = rng.randbytes(len(pixels))
        noisy = bytes(max(0, min(255, value + sample % 61 - 30)) for value, sample in zip(pixels, noise))
        contrast_png = pymupdf.Pixmap(pymupdf.csGRAY, pix.width, pix.height, contrast, 0).tobytes('png')
        noise_png = pymupdf.Pixmap(pymupdf.csGRAY, pix.width, pix.height, noisy, 0).tobytes('png')
        normal = page.get_pixmap(dpi=160, colorspace=pymupdf.csGRAY).tobytes('png')
        rotated_images = {}
        for angle in (90, 180, 270):
            pixmap = page.get_pixmap(matrix=pymupdf.Matrix(160 / 72, 160 / 72).prerotate(angle),
                                     colorspace=pymupdf.csGRAY)
            rotated_images[angle] = pixmap.tobytes('png')

    for label, image in [('low_resolution', low), ('poor_contrast', contrast_png), ('moderate_noise', noise_png)]:
        with pymupdf.open() as scan:
            page = scan.new_page(width=595, height=842)
            page.insert_image(page.rect, stream=image)
            yield 'payslip_' + label, kind, 'pdf', scan.tobytes()
    with pymupdf.open() as cover:
        page = cover.new_page(width=595, height=842)
        page.insert_textbox(pymupdf.Rect(40, 80, 555, 500),
                            'LOCAL DEMO - PORTADA\nDocumento de prueba sin antecedentes reales.', fontsize=14)
        cover_png = page.get_pixmap(dpi=160, colorspace=pymupdf.csGRAY).tobytes('png')
    with pymupdf.open() as scan:
        for image in (cover_png, normal):
            page = scan.new_page(width=595, height=842)
            page.insert_image(page.rect, stream=image)
        yield 'payslip_two_pages', kind, 'pdf', scan.tobytes(deflate=True, deflate_images=True)
    # Unlike a PDF Rotate entry, the bitmap itself is sideways on an upright page.
    for angle, image in rotated_images.items():
        with pymupdf.open() as scan:
            width, height = (842, 595) if angle in (90, 270) else (595, 842)
            page = scan.new_page(width=width, height=height)
            page.insert_image(page.rect, stream=image)
            yield f'payslip_pixels_{angle}', kind, 'pdf', scan.tobytes(deflate=True, deflate_images=True)


def mixed_orientation_fixture(kind):
    import pymupdf
    content = ('LOCAL DEMO - CERTIFICADO LABORAL\nTipo de contrato: Indefinido\nFecha de emision: 25/10/2026',
               'LOCAL DEMO - ANTECEDENTES LABORALES\nFecha de ingreso: 01/10/2024')
    images = []
    for index, value in enumerate(content):
        with pymupdf.open() as source:
            page = source.new_page(width=595, height=842)
            page.insert_textbox(pymupdf.Rect(40, 80, 555, 500), value, fontsize=14)
            matrix = pymupdf.Matrix(160 / 72, 160 / 72).prerotate(90 if index else 0)
            images.append(page.get_pixmap(matrix=matrix, colorspace=pymupdf.csGRAY).tobytes('png'))
    with pymupdf.open() as document:
        for index, image in enumerate(images):
            width, height = (842, 595) if index else (595, 842)
            page = document.new_page(width=width, height=height)
            page.insert_image(page.rect, stream=image)
        yield 'employment_mixed_orientation', kind, 'pdf', document.tobytes(deflate=True, deflate_images=True)
